expect fun hmacSha256(key: ByteArray, data: ByteArray): ByteArray

expect fun currentTimeMillis(): Long

fun generateTotpPairFromBase32(
    base32Secret: String,
    timeMillis: Long = currentTimeMillis()
): Pair<String, String>? {
    val secret = decodeBase32(base32Secret)

    if (secret.isEmpty()) return null

    val currentToken = generateTotp(
        secret = decodeBase32(base32Secret),
        timeMillis = timeMillis,
        timeOffsetSeconds = 0
    )

    val futureToken = generateTotp(
        secret = decodeBase32(base32Secret),
        timeMillis = timeMillis,
        timeOffsetSeconds = 30
    )

    return Pair(currentToken, futureToken)
}


// ByteArray shouldn't be empty
private fun generateTotp(
    secret: ByteArray,
    timeMillis: Long = currentTimeMillis(),
    timeOffsetSeconds: Int
): String {
    val TIME_STEP_SECONDS = 30
    val DIGITS = 6

    // Convert counter to byte array
    val counter = (timeMillis / 1000L + timeOffsetSeconds) / TIME_STEP_SECONDS
    val counterBytes = ByteArray(8) { i -> ((counter shr (56 - i * 8)) and 0xFF).toByte() }

    // Compute HMAC-SHA1
    val hash = hmacSha1(secret, counterBytes)

    val offset = (hash.last() and 0x0F).toInt()

    val binary =
        ((hash[offset].toInt() and 0x7F) shl 24) or
                ((hash[offset + 1].toInt() and 0xFF) shl 16) or
                ((hash[offset + 2].toInt() and 0xFF) shl 8) or
                (hash[offset + 3].toInt() and 0xFF)

    val otp = binary % 10.0.pow(DIGITS).toInt()
    return otp.toString().padStart(DIGITS, '0')
}



private fun decodeBase32(input: String): ByteArray {
    val BASE32_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
    val cleaned = input.uppercase()

    var buffer = 0
    var bitsLeft = 0
    val output = ArrayList<Byte>()

    for (char in cleaned) {
        if (char == '=') continue // skip padding

        val value = BASE32_ALPHABET.indexOf(char)
        if (value == -1) return ByteArray(0)  // skip invalid characters, since totp is checked later

        buffer = (buffer shl 5) or value
        bitsLeft += 5

        if (bitsLeft >= 8) {
            bitsLeft -= 8
            output.add(((buffer shr bitsLeft) and 0xFF).toByte())
        }
    }

    return output.toByteArray()
}
